import { randomUUID } from "node:crypto";
import { CONTROL_API_HEADER, CONTROL_API_VERSION } from "@godseye/contracts";
import { expect, type Page, test } from "@playwright/test";
import { enrollConsoleOwner } from "./owner-fixture.js";

test.beforeEach(async ({ page, baseURL }, testInfo) => {
  await enrollConsoleOwner(page, baseURL, testInfo.project.metadata);
});
async function project(page: Page, prefix: string) {
  const name = `${prefix} ${randomUUID().slice(0, 8)}`;
  await page.goto("/projects/new");
  await page.getByLabel("Nom du projet", { exact: true }).fill(name);
  await page.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  const panel = page.getByRole("region", { name: "Backend applicatif", exact: true });
  await expect(panel.getByText("Non configuré", { exact: true })).toBeVisible();
  return {
    name,
    panel,
    form: panel.getByRole("form", { name: "Configurer le backend applicatif", exact: true }),
  };
}
async function configure(page: Page, form: ReturnType<Page["getByRole"]>) {
  await form
    .getByLabel("Origines autorisées, une par ligne", { exact: true })
    .fill("http://localhost:3000");
  const response = page.waitForResponse(
    (result) =>
      result.request().method() === "PUT" && new URL(result.url()).pathname.endsWith("/backend"),
  );
  await form.getByRole("button", { name: "Enregistrer le backend", exact: true }).click();
  expect((await response).status()).toBe(200);
}

test("T-AC-61 T-AC-62 persists per-environment application settings while keeping hosted runtime unconnected", async ({
  page,
}) => {
  const { panel, form } = await project(page, "Backend desktop");
  await form.getByLabel("Autoriser les inscriptions utilisateurs", { exact: true }).check();
  await form.getByLabel("Taille maximale d’un fichier (MiB)", { exact: true }).fill("8");
  await form.getByLabel("Quota total de fichiers (MiB)", { exact: true }).fill("32");
  await configure(page, form);
  await expect(panel.getByText("Configuration préparée", { exact: true })).toBeVisible();
  await expect(panel.getByText("Runtime hébergé non connecté", { exact: true })).toBeVisible();
  await expect(
    panel.getByText(
      "Configuration du backend enregistrée. Aucun service distant n’a été démarré.",
      { exact: true },
    ),
  ).toBeVisible();
  await page.reload();
  await expect(
    form.getByLabel("Autoriser les inscriptions utilisateurs", { exact: true }),
  ).toBeChecked();
  await expect(form.getByLabel("Quota total de fichiers (MiB)", { exact: true })).toHaveValue("32");
  await panel
    .getByRole("combobox", { name: "Environnement du backend", exact: true })
    .selectOption({ label: "Production · production" });
  await expect(panel.getByText("Non configuré", { exact: true })).toBeVisible();
  await expect(form.getByLabel("Origines autorisées, une par ligne", { exact: true })).toHaveValue(
    "",
  );
  await page.locator("body").click({ position: { x: 1, y: 1 } });
  await page.screenshot({ path: "artifacts/backend-overview.png", fullPage: true });
});

test("T-AC-61 keeps mobile backend controls readable and saves an explicitly disabled configuration", async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  const { panel, form } = await project(page, "Backend mobile");
  await form.getByLabel("Backend activable par son runtime local", { exact: true }).uncheck();
  await configure(page, form);
  await expect(panel.getByText("Désactivé", { exact: true })).toBeVisible();
  for (const name of [
    "Confirmer mon identité",
    "Actualiser le backend",
    "Enregistrer le backend",
  ]) {
    const button = panel.getByRole("button", { name, exact: true });
    await button.scrollIntoViewIfNeeded();
    const bounds = await button.evaluate((element) => {
      const rect = element.getBoundingClientRect();
      const text = document.createRange();
      text.selectNodeContents(element);
      let unclipped = true;
      for (let parent = element.parentElement; parent; parent = parent.parentElement) {
        if (getComputedStyle(parent).overflowX !== "visible") {
          const clip = parent.getBoundingClientRect();
          unclipped &&= rect.left >= clip.left - 1 && rect.right <= clip.right + 1;
        }
      }
      return {
        inViewport: rect.left >= 0 && rect.right <= innerWidth,
        unclipped,
        textFits: Array.from(text.getClientRects()).every(
          (box) => box.left >= rect.left - 1 && box.right <= rect.right + 1,
        ),
      };
    });
    expect(bounds).toEqual({ inViewport: true, unclipped: true, textFits: true });
  }
  await page.locator("body").click({ position: { x: 1, y: 1 } });
  await page.screenshot({ path: "artifacts/backend-mobile.png", fullPage: true });
});

test("T-AC-61 rejects browser runtime-material claims and wildcard origins without persisting them", async ({
  page,
}) => {
  const { panel, form } = await project(page, "Backend boundary");
  const marker = `synthetic-private-value-${randomUUID()}`;
  const result = await page.evaluate(
    async ({ marker, header, version }) => {
      const projectId = location.pathname.split("/").at(-1);
      const projects = (await (await fetch(`/api/v1/projects/${projectId}`)).json()) as {
        revision: number;
        environments: { id: string; revision: number }[];
      };
      const environment = projects.environments[0];
      if (!environment) throw new Error("Synthetic backend environment absent");
      const response = await fetch(
        `/api/v1/projects/${projectId}/environments/${environment.id}/backend`,
        {
          method: "PUT",
          headers: {
            "content-type": "application/json",
            "idempotency-key": crypto.randomUUID(),
            [header]: version,
          },
          body: JSON.stringify({
            expectedRevision: 0,
            expectedProjectRevision: projects.revision,
            expectedEnvironmentRevision: environment.revision,
            authMaterial: marker,
            configuration: {
              enabled: true,
              registrationEnabled: true,
              allowedOrigins: ["https://*.example.test"],
              maxFileMiB: 8,
              storageMiB: 32,
              maxFiles: 10,
              eventRetention: 100,
            },
          }),
        },
      );
      return { status: response.status, body: await response.text() };
    },
    { marker, header: CONTROL_API_HEADER, version: CONTROL_API_VERSION },
  );
  expect(result.status).toBe(422);
  expect(result.body).not.toContain(marker);
  await panel.getByRole("button", { name: "Actualiser le backend", exact: true }).click();
  await expect(panel.getByText("Non configuré", { exact: true })).toBeVisible();
  await expect(form.getByLabel("Origines autorisées, une par ligne", { exact: true })).toHaveValue(
    "",
  );
});
